{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative (sentiment < 0.0) or shows early signs of decline.",
    "Reduce forecast overshoot after sharp upward spikes (e.g., >70% above recent peak) by applying a 10-15% dampening factor.",
    "Apply mean reversion bias: if forecast is >10% above 15-day moving average, reduce by 5-8% per day until convergence.",
    "For long-term (30-day) forecasts, cap upward revisions at +5% above recent 15-day high to avoid overconfidence.",
    "If sentiment is neutral (0.0) and forecast is consistently above true outcome, reduce by 2-3% per day to align with historical underperformance.",
    "When true outcome shows sharp downward trend (e.g., >5% drop from prior day), reduce forecast by 3-5% to avoid lagged overreaction."
  ]
}
